return function(Plasma)
	local create = Plasma.create
	return Plasma.widget(function(children, options)
		options = options or {}
		local style = Plasma.useStyle()
		local refs = Plasma.useInstance(function(ref)
			local frame = create("ScrollingFrame", {
				BackgroundTransparency = 1,
				VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar,
				HorizontalScrollBarInset = Enum.ScrollBarInset.ScrollBar,
				BorderSizePixel = 0,
				ScrollBarThickness = 6,
				Size = UDim2.new(0, 0, 0, 750),
				AutomaticSize = Enum.AutomaticSize.X,
				AutomaticCanvasSize = Enum.AutomaticSize.Y,
				CanvasSize = UDim2.new(0, 0, 0, 0),

				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					Padding = UDim.new(0, 10),
				}),
			})
			ref.frame = frame
			return frame
		end)
		refs.frame.Size = options.Size or UDim2.new(0, 0, 0, 750)
		Plasma.scope(children)
		return refs.frame
	end)
end
